package org.millenaire.common.village;import java.util.*;import net.minecraft.world.item.*;import org.millenaire.common.utilities.Point;public class Building{public Map<Item,Integer> stock=new HashMap<>();public List<ItemStack> stored=new ArrayList<>();public boolean rejectStore,rejectTake;public final Resources res=new Resources();public static class Resources{public List<Point> brewingStands=new ArrayList<>();}public Resources getResManager(){return res;}public int countGoods(Item item){return stock.getOrDefault(item,0);}public int countGoods(Item item,int meta){return countGoods(item)+stored.size();}public int takeGoods(Item item,int n){int got=rejectTake?0:Math.min(n,countGoods(item));stock.put(item,countGoods(item)-got);return got;}public boolean storeItemStack(ItemStack s){if(rejectStore)return false;stored.add(s.copy());return true;}}